let data = $input.item.json;
if (Array.isArray(data)) {
  data = data[0];
}

const text = data.ParsedResults[0].ParsedText;

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
const vendor = lines[0].replace(/^#\s*/, '').replace(/\t/g, ' ').trim();

const dateMatch = text.match(/Date:\s*(\d{4}-\d{2}-\d{2})/i);
const date = dateMatch ? dateMatch[1] : null;

// \b ensures we match the word "TOTAL" itself, not "total" inside "Subtotal"
const totalMatch = text.match(/\bTOTAL\b\s+(SAR|USD|AED)?\s*[\r\n\t]*([\d,]+\.\d{2})/i);
const currency = totalMatch && totalMatch[1] ? totalMatch[1].toUpperCase() : 'SAR';
const amount = totalMatch ? parseFloat(totalMatch[2].replace(/,/g, '')) : null;

return {
  json: {
    Vendor: vendor,
    Date: date,
    Amount: amount,
    Currency: currency
  }
};

